var e=[{id:`n_1`,type:`scene_change`,speaker:null,text:null,stage:{bg:`HALL`,bg_animation:null,bgm:`CUTSCENE_FLASHBACK`,filter:`NCFT_NORMAL`,slots:{L:null,C:null,R:null}}},{id:`n_2`,type:`dialog`,speaker:`SIGMA_RAS_NULL_SPECIAL`,text:{KOREA:`난 지금이 너무 행복해. 이 순간을 멈춘 채로 영원히 간직하고 싶어. 아빠도 같이 요정님께 소원을 빌자. 앞으로도 계속 이만큼 행복하게 해달라고 말이야.`,JPN:`私、今すごく幸せ。この刹那を止めて永遠にとっておきたいぐらい。パパも妖精さんにお願いしよう？　今感じる幸せが、いつまでも続きますようにって。`,ENG:`I'm so happy right now. I want to keep this moment forever, just like this. Let's make a wish to the Fairy Godmother together, Daddy. So we can stay this happy forever.`,TWN:`我現在非常幸福。想把這個瞬間永遠定格，珍藏起來。爸爸，我們一起向仙女許願吧，祈求我們能永遠像現在這樣幸福。`},stage:{bg:`HALL`,bg_animation:null,bgm:`CUTSCENE_FLASHBACK`,filter:`NCFT_NORMAL`,slots:{L:null,C:{char_id:`SIGMA_RAS_NULL_SPECIAL`,face:`UNIT_LAUGH`,hologram:!1},R:null}}}];export{e as default};